page("picnic-burgers-on-a-portable-grill","Picnic Burgers on a Portable Grill","Classic burgers prepped at home and grilled at the park or tailgate on a portable charcoal grill.","c28",recipe(
"<p>Form the patties at home, stack them between parchment in a sealed container, and the cook at the park takes 15 minutes.</p>",
"4","15 minutes at the grill",["1½ lb ground beef, 80/20, formed into 4 patties with a thumbprint in the center","Salt and pepper","4 buns, cheese, lettuce, tomato, onion"],
["At home: form patties, stack with parchment, seal, keep cold.","Light a chimney; build a two-zone fire.","Season patties; grill over coals 3 to 4 minutes per side.","Add cheese; move to the cool side if flaring.","Cook to 160°F. Toast buns on the cool side."],
tips=["Press only once with the thumbprint, not with the spatula during cooking."]),"recipes",[])

page("foil-packet-potatoes-and-sausage","Foil-Packet Potatoes and Sausage","An easy one-packet dinner of smoked sausage, potatoes and peppers cooked on a portable charcoal grill.","c13",recipe(
"<p>Foil packets are the easiest portable dinner: prep at home, cook on the grate, eat from the foil, almost no cleanup.</p>",
"4","40 minutes",["1 lb precooked smoked sausage, sliced","1½ lb small potatoes, quartered (or parboiled at home to save time)","1 bell pepper, 1 onion, chopped","2 tbsp oil, 1 tsp salt, 1 tsp paprika, ½ tsp garlic powder","Heavy-duty foil"],
["Toss everything with oil and seasoning.","Divide among 4 double-layer foil sheets; fold into sealed packets.","Grill over medium coals, turning every 8 to 10 minutes, 25 to 35 minutes, until potatoes are tender.","Check sausage reaches 165°F. Open carefully: steam burns."],
tips=["Parboiled potatoes cut the time roughly in half."]),"recipes",[])

page("griddle-pancakes-and-bacon","Griddle Pancakes and Bacon","Camp breakfast on a griddle plate over charcoal: bacon first, then pancakes on the same plate.","grid1",recipe(
"<p>A <a href='"+GRID+"'>griddle plate</a> over a modest bed of coals turns a portable grill into a breakfast station.</p>",
"4","30 minutes",["8 slices bacon","Pancake mix for about 12 pancakes (pre-mixed dry at home; add water or milk and egg at camp)","Butter, syrup"],
["Light a half chimney; spread coals thin under the griddle.","Cook bacon on the plate until crisp. Set aside; wipe most of the fat.","Ladle pancakes onto a medium-hot area. Flip when bubbles form and edges look set.","Cook until golden and cooked through."],
tips=["Keep a cooler zone for pancakes; the hot zone burns them.","Bring pre-mixed dry ingredients in a bag."]),"recipes",[])

page("griddle-grilled-cheese-and-quesadillas","Grilled Cheese and Quesadillas on a Griddle Plate","Fast, kid-friendly lunches on a portable grill's griddle plate.","grid2",recipe(
"<p>A quick lunch that every age eats. Great for parks and beaches.</p>",
"4","20 minutes",["8 slices bread and butter, or 8 tortillas","Sliced or shredded cheese","Optional: cooked chicken, ham, beans, peppers"],
["Light a small fire; coals thin under the griddle.","Butter bread outside; fill with cheese (and any precooked fillings).","Cook on the griddle 2 to 3 minutes per side until golden and melted.","Heat any meat fillings to 165°F."],
tips=["Low heat melts cheese before bread burns."]),"recipes",[])

page("teriyaki-chicken-skewers","Teriyaki Chicken Skewers","Teriyaki chicken skewers marinated at home and grilled at camp on a portable charcoal grill.","c08",recipe(
"<p>Skewers fit crosswise on a narrow grill and cook fast. Marinate at home in a sealed bag.</p>",
"4","20 minutes at the grill, plus marinating",["1½ lb boneless chicken thighs, cubed","½ cup teriyaki sauce (half reserved, never touched raw chicken, for basting)","Skewers (soak wooden ones)","Green onion, sesame seeds"],
["Marinate chicken in half the sauce, 1 to 8 hours, in the fridge or cold cooler.","Thread onto skewers; discard used marinade.","Grill over medium coals, turning every few minutes, 10 to 12 minutes.","Brush with reserved sauce in the last minutes.","Cook to 165°F. Top with green onion and sesame."],
tips=["Sugary sauces burn; baste late and move to the cool side if needed."]),"recipes",[])

page("garlic-butter-shrimp-skewers","Garlic Butter Shrimp Skewers","Quick shrimp skewers with garlic butter on a portable charcoal grill: about 5 minutes over hot coals.","c28",recipe(
"<p>Shrimp cooks in minutes, perfect for a beach or boat-day shore cook. Keep it on ice until it hits the grill.</p>",
"4","20 minutes",["1½ lb large shrimp, peeled and deveined","3 tbsp melted butter, 2 cloves garlic, pinch of salt, lemon","Skewers"],
["Thread shrimp on two parallel skewers so they don't spin.","Brush with garlic butter.","Grill over hot coals 2 to 3 minutes per side, until pink and opaque (145°F).","Squeeze lemon over."],
tips=["Don't overcook; shrimp turns rubbery fast."]),"recipes",[])

page("grilled-portobello-and-veggie-plate","Grilled Portobello and Veggie Plate","A meatless portable grill meal: marinated portobellos, zucchini, peppers and corn over charcoal.","c13",recipe(
"<p>A colorful plate for vegetarians or a side for everyone.</p>",
"4","30 minutes",["4 portobello caps","2 zucchini, sliced lengthwise","2 bell peppers, quartered","2 ears corn","¼ cup olive oil, 2 tbsp balsamic vinegar, 1 clove garlic, salt, pepper"],
["Toss vegetables with the oil mixture.","Grill over medium coals, turning, until tender and marked: peppers and zucchini 6 to 8 minutes, mushrooms 8 to 10, corn 10 to 15.","Slice and serve with bread or in buns."],
tips=["Grill vegetables before meat if sharing the grill, or use separate tongs."]),"recipes",[])
